import{_ as o,a0 as u,w as s,s as l,ao as d,I as r,x as e,a1 as p,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const U=JSON.parse('{"title":"如何將 Ubuntu14.04 安全的升級到14.10 | LCTT x X-CMD","titleTemplate":false,"description":"如何將 Ubuntu14.04 安全的升級到14.10 | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何將 Ubuntu14.04 安全的升級到14.10 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何將 Ubuntu14.04 安全的升級到14.10 | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20141024 How To Upgrade Ubuntu 14.04 Trusty To Ubuntu 14.10 Utopic","title":"如何將 Ubuntu14.04 安全的升級到14.10","tag":"201411","desc":""},"relativePath":"201411/20141024 How To Upgrade Ubuntu 14.04 Trusty To Ubuntu 14.10 Utopic.md","filePath":"[post].md"}'),i={name:"201411/20141024 How To Upgrade Ubuntu 14.04 Trusty To Ubuntu 14.10 Utopic.md"};function g(m,t,b,c,h,T){const n=u("Link");return s(),l("div",null,[t[11]||(t[11]=d(`<h1 id="如何將-ubuntu14-04-安全的升級到14-10" tabindex="-1">如何將 Ubuntu14.04 安全的升級到14.10 <a class="header-anchor" href="#如何將-ubuntu14-04-安全的升級到14-10" aria-label="Permalink to “如何將 Ubuntu14.04 安全的升級到14.10”">​</a></h1><p>如果想從Ubuntu14.04/13.10/13.04/12.10/12.04或者更老的版本升級到14.10，只要遵循下面給出的步驟。注意，你不能直接從13.10升級到14.10。你應該先將13.10升級到14.04在從14.04升級到14.10。下面是詳細步驟。</p><p>下面的步驟不僅能用於14.10，也兼容於一些像Lubuntu14.10，Kubuntu14.10和Xubuntu14.10等的Ubuntu衍生版本</p><p><strong>重要</strong>：在升級之前，保險起見，不要忘了將你的數據在U盤或外部硬盤上保存一下。</p><h3 id="桌面升級" tabindex="-1">桌面升級 <a class="header-anchor" href="#桌面升級" aria-label="Permalink to “桌面升級”">​</a></h3><p>在升級之前，我們要先更新系統。打開終端輸入以下命令</p><pre><code>sudo apt-get update &amp;&amp; sudo apt-get dist-upgrade
</code></pre><p>上面的命令會下載安裝最新的包。</p><p>重啓你的電腦以完成更新。</p><p>然後輸入下面的命令來升級到新的可獲得的版本</p><pre><code>sudo update-manager -d
</code></pre><p>軟件更新器會出現並且搜索新的發行版。</p><p>幾秒鐘之後，你會在屏幕中看到如下字樣：<strong>ubuntu14.10現在可以獲得(你現在是14.04系統)</strong>。點擊升級按鈕開始升級。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/10/Software-Updater_001.png" alt=""></p><p>軟件更新器會提示你確定更新。點擊開始更新開始安裝14.10</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/10/Release-Notes_002.png" alt=""></p><p><strong>請注意</strong>：這是beta版本。不要在生產用的機器上安裝。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/10/Distribution-Upgrade_003.png" alt=""></p><p>幾分鐘之後，軟件更新器會提醒你一些將被移除的和將被安裝的軟件包的詳細信息。點擊<strong>開始升級</strong>繼續。確保你更新時在穩定的網絡下。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/10/Untitled-window_004.png" alt=""></p><p>現在，更新程序會開始獲取新的軟件包。獲取速度取決於你的網速。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/10/Distribution-Upgrade_005.png" alt=""></p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/10/Distribution-Upgrade_001.png" alt=""></p><p>之後，你會被詢問是否移除不必要的應用程序。最後，點擊<strong>重啓</strong>來完成整個升級過程。</p><p>這時侯，恭喜你已經成功的升級到了ubuntu14.10</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/10/Details_002.png" alt=""></p><p>你可以開始使用新的ubuntu版本了。</p><h3 id="服務器升級" tabindex="-1">服務器升級 <a class="header-anchor" href="#服務器升級" aria-label="Permalink to “服務器升級”">​</a></h3><p>從ubuntu14.04的服務器升級到14.10的服務器，採用下面的步驟。</p><p>安裝update-manager-core 這個包如果之前沒唷安裝的話：</p><pre><code>sudo apt-get install update-manager-core
</code></pre><p>編輯 /etc/update-manager/release-upgrades這個文件。</p><pre><code>sudo nano /etc/update-manager/release-upgrades
</code></pre><p>像下面那樣設置Prompt=normal或者Prompt=lts</p><pre><code># Default behavior for the release upgrader.

[DEFAULT]
# Default prompting behavior, valid options:
#
#  never  - Never check for a new release.
#  normal - Check to see if a new release is available.  If more than one new
#           release is found, the release upgrader will attempt to upgrade to
#           the release that immediately succeeds the currently-running
#           release.
#  lts    - Check to see if a new LTS release is available.  The upgrader
#           will attempt to upgrade to the first LTS release available after
#           the currently-running one.  Note that this option should not be
#           used if the currently-running release is not itself an LTS
#           release, since in that case the upgrader won&#39;t be able to
#           determine if a newer release is available.
Prompt=normal
</code></pre><p>現在可以通過下面的命令來更新你的服務系統了。</p><pre><code>sudo do-release-upgrade -d
</code></pre><p>直到屏幕提示你已完成。</p><hr>`,39)),r("p",null,[t[1]||(t[1]=e("via: ",-1)),p(n,{href:"http://www.unixmen.com/upgrade-ubuntu-14-04-trusty-ubuntu-14-10-utopic/"},{default:a(()=>[...t[0]||(t[0]=[e("http://www.unixmen.com/upgrade-ubuntu-14-04-trusty-ubuntu-14-10-utopic/",-1)])]),_:1})]),r("p",null,[t[4]||(t[4]=e("作者：SK 譯者：",-1)),p(n,{href:"https://github.com/johnhoow"},{default:a(()=>[...t[2]||(t[2]=[e("johnhoow",-1)])]),_:1}),t[5]||(t[5]=e(" 校對：",-1)),p(n,{href:"https://github.com/wxy"},{default:a(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[8]||(t[8]=e("本文由 ",-1)),p(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原創翻譯，",-1)),p(n,{href:"http://linux.cn/"},{default:a(()=>[...t[7]||(t[7]=[e("Linux中國",-1)])]),_:1}),t[10]||(t[10]=e(" 榮譽推出",-1))])])}const _=o(i,[["render",g]]);export{U as __pageData,_ as default};
